import { Component, OnInit } from '@angular/core';

@Component({
  selector: 'app-corner-cat',
  templateUrl: './corner-cat.component.html',
  styleUrls: ['./corner-cat.component.css']
})
export class CornerCatComponent implements OnInit {
  showCat = false;

  constructor() { }

  ngOnInit(): void {

    setTimeout(() => {
      this.showCat = true;
    }, 1500);
  }
}
